#!/usr/bin/env python3
"""Build the private, offline PDF adapter from byte-checked upstream bundles."""
import hashlib,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def build():
 root=ROOT/'vendor/pdf-export';meta=json.loads((root/'manifest.json').read_text())
 for info in meta.values():
  for name,digest in info['files'].items():
   assert hashlib.sha256((root/name).read_bytes()).hexdigest()==digest,name
 def read(name):return re.sub(r'//# sourceMappingURL=[^\n]*','',(root/name).read_text())
 code='// Generated by scripts/vendor-pdf-export.py; private upstream module scopes.\n'
 code+='const pdf=(()=>{const module={exports:{}};const exports=module.exports;\n'+read('jspdf.umd.min.js')+'\nreturn module.exports;})();\n'
 svg=read('svg2pdf.umd.min.js')
 # Private, version-checked adapter: prepared PDF images never enter the DOM
 # image decoder or jsPDF's PNG decode/recompression pipeline. Ordinary SVG
 # images keep the unmodified upstream path. Do not change vendored bytes.
 old='a.imageUrl=a.element.getAttribute("xlink:href")'
 new='a.imageUrl=a.element.getAttribute("data-laymesh-image")||a.element.getAttribute("xlink:href")'
 assert svg.count(old)==1
 svg=svg.replace(old,new)
 old='a.imageLoadingPromise=e.fetchImageData(a.imageUrl)'
 new='a.imageLoadingPromise=a.imageUrl.startsWith("laymesh-pdf:")?Promise.resolve(null):e.fetchImageData(a.imageUrl)'
 assert svg.count(old)==1
 svg=svg.replace(old,new)
 old='case 0:return this.imageLoadingPromise?('
 new='case 0:if(t.svg2pdfParameters.laymeshImage&&t.svg2pdfParameters.laymeshImage(t.pdf,this.imageUrl,this.element,t.transform))return[2];return this.imageLoadingPromise?('
 assert svg.count(old)==1
 svg=svg.replace(old,new)
 code+='(()=>{const module={exports:{}};const exports=module.exports;const require=(name)=>{if(name==="jspdf")return pdf;throw Error("Unbundled PDF dependency: "+name);};\n'+svg+'\n})();\nexport const jsPDF=pdf.jsPDF;\n'
 dest=ROOT/'site/vendor/pdf-export';dest.mkdir(exist_ok=True)
 (dest/'index.js').write_text(code)
 (dest/'LICENSE').write_text('\n\n'.join((root/p).read_text() for i in meta.values() for p in i['files'] if 'LICENSE' in p))
 manifest=ROOT/'site/vendor/manifest.json';m=json.loads(manifest.read_text())
 m['pdf-export']={'version':'jspdf-4.2.1_svg2pdf-2.8.1','entry':'pdf-export/index.js','sha256':hashlib.sha256((dest/'index.js').read_bytes()).hexdigest(),'license':'pdf-export/LICENSE'}
 manifest.write_text(json.dumps(m,indent=2)+'\n')
if __name__=='__main__':build()
